param([ValidateSet('BASELINE','REMEDIATION')][string]$Condition='BASELINE',[switch]$Finalize)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;. (Join-Path $PSScriptRoot 'experiment-1-22-native-log-capture.ps1');$out=Join-Path $root 'backend\experiments\results\experiment-1-22\post-stop-preflight';New-Item -ItemType Directory -Force $out|Out-Null
$files=@('backend\docker-compose.experiment.yaml','backend\docker-compose.app-instance-t3-medium.yaml','backend\docker-compose.mock-headroom-4cpu.yaml','backend\docker-compose.http-pool-400.yaml','backend\docker-compose.mock-memory-headroom.yaml','backend\docker-compose.experiment-1-12-connection-attribution.yaml','backend\docker-compose.experiment-1-19-fresh-first-lifecycle.yaml');$args=@();foreach($f in $files){$args+=@('-f',(Join-Path $root $f))};$project='doeng-exp122-post-stop-probe';$app='doeng-flux-exp119-fresh-first-20260803:latest';$mock='doeng-exp119-mock-frozen-20260803:latest';function Health($u){$end=(Get-Date).AddSeconds(90);while((Get-Date)-lt$end){try{if((Invoke-WebRequest -UseBasicParsing $u -TimeoutSec 3).StatusCode-eq200){return}}catch{};Start-Sleep 1};throw 'Health failed'}
if($Finalize){$b=Get-Content (Join-Path $out 'baseline.json')-Raw|ConvertFrom-Json;$r=Get-Content (Join-Path $out 'remediation.json')-Raw|ConvertFrom-Json;if($b.status-ne'POST_STOP_APPLICATION_LOG_CAPTURE_PROBE_READY'-or$r.status-ne'POST_STOP_APPLICATION_LOG_CAPTURE_PROBE_READY'){throw 'Post-stop preflight not ready'};[ordered]@{state='EXP122_READY_FOR_SIX_CORE_RUNS';warmup=0;k6=0;core=0}|ConvertTo-Json|Set-Content (Join-Path $out 'finalize.json');exit 0}
$policy=if($Condition-eq'BASELINE'){@{leasingStrategy='FIFO';maxIdleTimeMs='0';evictionIntervalMs='0'}}else{@{leasingStrategy='LIFO';maxIdleTimeMs='3000';evictionIntervalMs='1000'}};$dir=Join-Path $out $Condition.ToLower();if(Test-Path $dir){Remove-Item $dir -Recurse -Force};New-Item -ItemType Directory $dir|Out-Null;$env:DOENG_EXP119_APP_IMAGE=$app;$env:DOENG_EXP119_MOCK_IMAGE=$mock;$env:DOENG_EXTERNAL_LEASING_STRATEGY=$policy.leasingStrategy;$env:DOENG_EXTERNAL_MAX_IDLE_TIME_MS=$policy.maxIdleTimeMs;$env:DOENG_EXTERNAL_EVICTION_INTERVAL_MS=$policy.evictionIntervalMs
try{docker compose -p $project @args up -d --force-recreate --no-build mariadb experiment-mock flux-corrected;if($LASTEXITCODE){throw 'Compose failed'};Health 'http://127.0.0.1:9001/actuator/health';$container=(docker compose -p $project @args ps -q flux-corrected).Trim();docker compose -p $project @args stop -t 15 flux-corrected;if($LASTEXITCODE-ne0){throw 'Stop failed'};$stopExit=$LASTEXITCODE;$state=(docker inspect --format '{{.State.Status}}' $container).Trim();if($state-match'running'){throw 'Container still running'};$capture=Invoke-Exp122PostStopLogCapture -RunId "PROBE-EXP122-$Condition" -ContainerId $container -ApplicationDirectory (Join-Path $dir 'application') -TimeoutSeconds 30 -ContainerStateAtCapture $state;[ordered]@{condition=$Condition;status='POST_STOP_APPLICATION_LOG_CAPTURE_PROBE_READY';policy=$policy;stopExitCode=$stopExit;stateAfter=$state;capture=$capture;warmup=0;k6=0;core=0}|ConvertTo-Json -Depth 10|Set-Content (Join-Path $out "$($Condition.ToLower()).json") -Encoding UTF8}finally{docker compose -p $project @args down --remove-orphans|Out-Null}
